#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    // If no argument is provided, the original program considered the input balanced.
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *s = argv[1];
    // Simple stack for opening brackets. Size is generous for typical inputs.
    char stack[4096];
    int sp = 0; // stack pointer (number of elements)

    for (size_t i = 0; s[i] != '\0'; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (sp >= (int)sizeof(stack)) {
                // Overflow – treat as unbalanced (should never happen for realistic inputs).
                puts("UNBALANCED");
                return 0;
            }
            stack[sp++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (sp == 0) {
                puts("UNBALANCED");
                return 0;
            }
            char open = stack[--sp];
            if ((open == '(' && c != ')') ||
                (open == '[' && c != ']') ||
                (open == '{' && c != '}')) {
                puts("UNBALANCED");
                return 0;
            }
        } else {
            // Non‑bracket characters are ignored – they do not affect balance.
            continue;
        }
    }

    if (sp == 0) {
        puts("BALANCED");
    } else {
        puts("UNBALANCED");
    }
    return 0;
}
